			waitColumns: conf.wait,
			readyColumns: conf.ready,
			leadColumns: conf.lead,
			cycleColumns: conf.cycle,
			workColumnsSet: columnIdArrayToSet(conf.work),
			waitColumnsSet: columnIdArrayToSet(conf.wait),
			readyColumnsSet: columnIdArrayToSet(conf.ready),
			leadColumnsSet: columnIdArrayToSet(conf.lead),
			cycleColumnsSet: columnIdArrayToSet(conf.cycle),
			currentDayBoardTime: -1,
			nextDayBoardTime: -1,
			currentPeriodBoardTime: -1,
			nextPeriodBoardTime: -1,
			lastDayBoardTime: -1,
			periodSize: conf.periodSize,
			periodType: conf.periodType,
			periodsInStat: conf.analyzeLength,
			noReworkTime: conf.noReworkTime,
			today: DateTime.now().startOf("day").toMillis(),
			now: DateTime.now().toMillis(),
			firstTime: -1,
			wiaCycleColumns: {},
