				timeWork.push(calcIssueStat.work);
				timeCycle.push(calcIssueStat.cycle);
				timeWait.push(calcIssueStat.wait);
				timeLife.push(calcIssueStat.life);
				timeRework.push(calcIssueStat.rework);
