		for (const id of tmp.workColumns) periodDayAWIPWork = sumTwo(periodDayAWIPWork, issueStat.times[id]);
		if (tmp.workColumnsSet.has(issueStat.lastCol)) periodDayAWIPWork = sumTwo(periodDayAWIPWork, tmp.nextDayBoardTime - issueStat.lastAct);
		for (const id of tmp.waitColumns) periodDayAWIPWait = sumTwo(periodDayAWIPWait, issueStat.times[id]);
		if (tmp.waitColumnsSet.has(issueStat.lastCol)) periodDayAWIPWait = sumTwo(periodDayAWIPWait, tmp.nextDayBoardTime - issueStat.lastAct);
		for (const id in tmp.columns) periodDayAWIPCol[id] = sumTwo(periodDayAWIPCol[id], issueStat.times[id]);
		periodDayAWIPCol[issueStat.lastCol] = sumTwo(periodDayAWIPCol[issueStat.lastCol], tmp.nextDayBoardTime - issueStat.lastAct);
